from pathlib import Path
import json,re,hashlib
D=Path('evidence/pv-b3q2-20261031');H=D/'host';lean=[];native=[]
for p in sorted(H.glob('*/receipt/receipt.json')):
 r=json.loads(p.read_text());r['evidence_path']=str(p)
