ids=[r['attempt']for r in lean];assert len(set(ids))==80 and sorted(ids)==list(range(77000,77077))+[77097,77098,77099]
allowed={'propext','Classical.choice','Quot.sound'};frozen=json.load(open(D/'frozen-manifest.json'));wanted={n for r in frozen['focused']for n in r['theorems']}
audit=next(r for r in lean if r['attempt']==77098);log=Path(audit['evidence_path']).with_name('stdout.log').read_text();found={}
for m in re.finditer(r"'([^']+)' (does not depend on any axioms|depends on axioms:\s*\[([^\]]*)\])",log):
 axioms=[]if m[3]is None else[m.strip()for m in m[3].split(',')if m.strip()]
 normalized=[re.sub(r'\.\{[^}]*\}','',s)for s in axioms];assert set(normalized)<=allowed,(m[1],normalized)
 found[m[1]]=dict(printed=axioms,normalized=normalized)
assert set(found)==wanted,(set(found)-wanted,wanted-set(found))
for r in lean+native:
 limits=r['limits'];assert limits['memory.high']=='6442450944'and limits['memory.max']=='8589934592'and limits['memory.swap.max']=='0'and limits['pids.max']=='64'
 assert r['swaps']==0
 gate=Path(r['evidence_path']).parent.parent
 for n in ['reservation.json','barrier.json']:assert json.loads((gate/n).read_text())['allowed']is True
 if 'source_sha256'in r:
  snap=gate/'source.lean';assert hashlib.sha256(snap.read_bytes()).hexdigest()==r['source_sha256']
for a in [77097,77098,77099]:assert next(r for r in lean if r['attempt']==a)['exit_status']==0
records=[{k:r.get(k)for k in ['attempt','module','command','exit_status','wall_seconds','peak_rss_kib','swaps','source_revision','source_sha256','guard_sha256','evidence_path','quiet_window']}for r in lean+native]
x=dict(lean_attempts=80,lean_exit_zero=sum(r['exit_status']==0 for r in lean),lean_nonzero=sum(r['exit_status']!=0 for r in lean),native_scopes=22,native_exit_zero=sum(r['exit_status']==0 for r in native),native_nonzero=sum(r['exit_status']!=0 for r in native),kani_runs=0,audited_theorems=len(found),axioms=found,standard_only=True,full_manifest_replays=1,proof_revision='be4bd9576167b482a03b28679e56f90d41799d9d',endpoint_premises_removed=0,endpoint_premises_added=0,endpoint_premises_weakened=0,resource_admissions_verified=True,quiet_snapshot_limitation='Earlier explicit per-run marker snapshots absent; admissions/timestamps retained. Wrapper records marker+time from the final stage onward.',generator_check='56 source files regenerated byte identically; initial checker expected 57, corrected to 56 with no Lean source change.',receipts=records)
(D/'verification-summary.json').write_text(json.dumps(x,indent=2)+'\n')
